        if (pr != g_records.end()) { recordpos::Cand& l = c[recordpos::kSrcLast]; l.have = 1; l.x = pr->second.x; l.y = pr->second.y; l.z = pr->second.z; }
        std::string hk = RecordHomeOf(worldId);
