        if (m.type == (net::MsgType)kStoreMsgProfiles) { StoreOnProfiles(m.payload); continue; }
        if (g_profLobby && m.type != net::MSG_STORE_WELCOME && m.type != (net::MsgType)kStoreMsgRefuse) { ++g_profLobbyIgnored; continue; }
