namespace coop {
// T203 lever `platoonkill <worldId>`: declares every member of an AWAKE group dead through the engine's own Character::declareDead
// 0x7A5660 (the routine a fatal wound ends in), so the death watch, the sleep-time delete and the bitmap run exactly as they would
// after a massacre. A test lever, not a game feature.
static unsigned long long kStDeclareDeadRva = 0; static coop::AddrReg kStDeclareDeadRva_reg("DeclareDead", &kStDeclareDeadRva);   /* stage 7/9: the address table fills this. Steam_1.0.65 0x7A5660 */
typedef void (*DeclareDeadFn)(void* character);
// review-p5j HIGH-2: no longer static and no longer only a lever. `worldstate.cpp` needs the SAME path to apply a
// received death to a unique this game has loaded - writing the state map alone leaves the character walking about.
int StoreDeclareDeadPod(void* c) { if (kStDeclareDeadRva == 0) return 0; __try { ((DeclareDeadFn)(uintptr_t)coop::AddrAbs(kStDeclareDeadRva))(c); return 1; } __except (EXCEPTION_EXECUTE_HANDLER) { return 0; } }
// par6 fold (review-par6 #3): a call that did not fault is not a death - since par6 a COPY's declareDead is refused by the copy
// death gate (the owner decides), so every kill lever reads the character back with this before it counts a kill.
int StoreIsDeadPod(void* c) { __try { return ((::Character*)c)->hasDied() ? 1 : 0; } __except (EXCEPTION_EXECUTE_HANDLER) { return -1; } }
// review-p5j MEDIUM-2: the thread id the store captured at its first tick, published so every other file's detours can
// say which thread they ran on. 0 means "not yet known", and every caller must read that as NOT the main thread.
unsigned long StoreMainThreadId() { return (unsigned long)g_storeMainThread; }
// `platoonkill nearest`: the awake WORLD group nearest the watched player (T203: a named group had gone on ice by the time the lever ran)
static bool PlatoonKillNearest(std::string* chosen)
{
    ::Character* pc = GetTarget(); float px = 0, pz = 0;
    if (!Plaus(pc) || !ReadCharPosPod(pc, &px, &pz)) return false;
    FmPod fm; if (!Plaus(coop::GameWorldPtr()) || !ReadFactionsPod((void*)coop::GameWorldPtr()->factionDirectory, &fm) || !Plaus(fm.factions) || fm.count > 4096) return false;
    void* best = 0; float bestD = 1e30f;
    for (unsigned fi = 0; fi < fm.count; ++fi)
    {
        Faction* f = (Faction*)fm.factions[fi]; if (!Plaus(f) || IsPlayerFaction(f) || IsPeerFaction(f)) continue;
        ActiveListPod ap; if (!ReadActiveListPod((void*)f, &ap) || !Plaus(ap.items) || ap.count > 4096) continue;
        for (unsigned i = 0; i < ap.count; ++i)
        {
            void* p = ap.items[i]; Pod q; if (!Plaus(p) || !ReadPod(p, &q) || !Plaus(q.active) || q.activeChars <= 0 || !Plaus(q.members)) continue;
            float mx = 0, mz = 0; if (!Plaus(q.members[0]) || !ReadCharPosPod(q.members[0], &mx, &mz)) continue;
            const float d = (mx - px) * (mx - px) + (mz - pz) * (mz - pz); if (d < bestD) { bestD = d; best = p; }
        }
    }
    if (best == 0) return false;
    *chosen = WorldIdOf(best); return !chosen->empty();
}
bool PlatoonKill(const std::string& worldIdIn)
{
    std::string worldId = worldIdIn;
    if (worldId == "nearest") { if (!PlatoonKillNearest(&worldId)) { DebugLog("[STORE] platoonkill nearest: no awake world group near the player"); return false; } DebugLog("[STORE] platoonkill nearest -> '" + worldId + "'"); }
    if (!Plaus(coop::GameWorldPtr())) return false;
    FmPod fm; if (!ReadFactionsPod((void*)coop::GameWorldPtr()->factionDirectory, &fm) || !Plaus(fm.factions) || fm.count > 4096) return false;
    for (unsigned fi = 0; fi < fm.count; ++fi)
    {
        Faction* f = (Faction*)fm.factions[fi]; if (!Plaus(f)) continue;
        void* p = FindActivePlatoonImpl(f, worldId); if (p == 0) continue;
        Pod q; if (!ReadPod(p, &q) || !Plaus(q.active) || q.activeChars <= 0 || !Plaus(q.members)) { DebugLog("[STORE] platoonkill " + worldId + ": not awake or no members"); return false; }
        int killed = 0, faults = 0, refused = 0;   /* par6 fold (review-par6 #3): a kill counts only when the member reads dead after it */
        for (int i = 0; i < q.activeChars && i < 64; ++i)
        {
            void* c = q.members[i]; if (!Plaus(c)) continue;
            if (StoreDeclareDeadPod(c) != 1) ++faults; else if (StoreIsDeadPod(c) == 1) ++killed; else ++refused;
        }
        DebugLog("[STORE] platoonkill " + worldId + ": declared dead " + N(killed) + "/" + N(q.activeChars) + " faults=" + N(faults)
                 + (refused != 0 ? " refused=" + N(refused) + " (a copy - the owner decides)" : std::string())
                 + " (the watch should mark it within a second)");
        return killed > 0;
    }
    DebugLog("[STORE] platoonkill " + worldId + ": no awake group with that id"); return false;
}
}
namespace coop {
// E21 (T223) - THE `killnamed <name substring>` TEST LEVER. T223 aimed `platoonkill nearest` at Dust King Tower and it
// killed a ROAMING GROUP that happened to be nearer the player than the tower's own residents: no named character died,
// so no UNIQUE_STATE was ever sent and the run could not answer the question it was run for. Distance is not identity.
// This lever names the target instead: it walks the engine's own character update list - the same set the census and the
// world-state apply walk, with the same 20,000 refusal bound - and declares dead the FIRST loaded character whose
// game-data NAME contains the substring AND whose `Character::isUnique` says it is a named character. A test lever, not
// a game feature: it is reachable only from the command channel.
//
// The isUnique call below is a SECOND COPY of worldstate.cpp's guarded call, and that is deliberate rather than an
// oversight. What is duplicated is one address and one signature; `Character::isUnique` 0x505ED0 takes `this` in rcx and
// its whole body is a lookup in the character's OWN game-data property map at +0xF8 - it reads no shared map and
// allocates nothing - and it sits here beside the `declareDead` 0x7A5660 RVA this file already carries for the same
// reason. worldstate.cpp is being rewritten by a parallel effort; a test lever must not reach into a file another
// effort is holding open.
static unsigned long long kStIsUniqueRva = 0; static coop::AddrReg kStIsUniqueRva_reg("IsUnique", &kStIsUniqueRva);   /* stage 7/9: the address table fills this. Steam_1.0.65 0x505ED0 */
typedef bool (*KillNamedIsUniqueFn)(void*);
int KillNamedIsUniquePod(void* c)   // 1 named, 0 ordinary, -1 the call faulted
{
    if (kStIsUniqueRva == 0) return -1;
    __try { return ((KillNamedIsUniqueFn)(uintptr_t)coop::AddrAbs(kStIsUniqueRva))(c) != 0 ? 1 : 0; }
    __except (EXCEPTION_EXECUTE_HANDLER) { return -1; }
}
// The display NAME the census prints (`Dust King` at T223's tower) is `GameData::name`, reached through the character's
// own game-data pointer; the id that goes on the wire as a unique's identity is `GameData::stringID` beside it. Both are
// copied into the caller's buffers rather than returned as strings: a function containing __try may hold no object that
// needs unwinding (C2712).
int KillNamedReadPod(void* c, char* name, int nameCap, char* sid, int sidCap)
{
    __try
    {
        ::GameData* gd = ((::Character*)c)->getRecordDirect();
        if (!Plaus(gd)) return 0;
        const char* np = gd->name.c_str();     const size_t nl = gd->name.size();
        const char* sp = gd->stringID.c_str(); const size_t sl = gd->stringID.size();
        if (np == 0 || sp == 0 || nl >= (size_t)nameCap || sl >= (size_t)sidCap) return 0;
        std::memcpy(name, np, nl); name[nl] = 0;
        std::memcpy(sid, sp, sl);  sid[sl]  = 0;
        return 1;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { return 0; }
}
// E30-3 (P6p): THE ENGINE CALL, IN ITS OWN FRAME. A __try may not share a frame with a std::string
// temporary (C2712), and QuitViaMenu() below builds log lines - so the call the whole lever exists to make
// lives here. Returns 1 if the engine's exit path returned normally, -1 if it raised. Passing a null first
// argument is not a shortcut: 0x913050 never reads it (see build/patch_p6p.py for the byte-level read of
// the shipped image - RCX is written at +0x4E before it is ever read), and 2 is the value the engine's own
// `param_2 == 2` test accepts and from which it computes the length of its own "Exiting...." string.
static int QuitConfirmCallPod(uintptr_t fn)
{
    __try { ((void (*)(void*, int))fn)((void*)0, 2); return 1; }
    __except (EXCEPTION_EXECUTE_HANDLER) { return -1; }
}
// E30-3 (P6p) - QuitViaMenu(): the `quitmenu` verb's body. P6l hooked the in-game pause menu's
// exit-confirm accept path because that is the only writer of the engine's quit byte that runs with a
// world loaded and is not the window close; nothing could then reach it, because Kenshi ignores injected
// input (F010) and no run can click through a menu. This calls that path itself, on the main thread, at
// the patched address - so the P6l detour runs and the run's log carries the MENU line and a
// [STORE] QUIT (menu) line instead of the close line the harness normally produces.
//
// THE NO-WORLD GUARD IS NOT A POINTER TEST, and this is a correction rather than a preference: F034
// established that the GameWorld is a static inside the exe image, so `ou` is non-null from preload and a
// pointer check cannot tell the title screen from a live world (soak.h). GameplayRunning() is F337's
// answer to that exact question - "did the in-game frame counter advance since the last SoakTick" - which
// is false at the title screen, true in a live world, and still true during a freeze. `Plaus(ou)` is kept
// beside it as what it really is: a precondition on the pointer, not an answer about the world.
bool QuitViaMenu()
{
    if (!OnMainThread())
    {
        DebugLog("[STORE] quitmenu REFUSED: this is not the main thread (mainTid is 0 or does not match). The engine's exit path may only be entered from the pump that owns the window; nothing was called.");
        return false;
    }
    if (!g_menuHookOn || orig_quitConfirm == 0)
    {
        DebugLog("[STORE] quitmenu REFUSED: the menu-quit hook is not armed (hook=installed is read back from the PROLOGUE BYTES, not from AddHook, and it is false - or its trampoline is null). Quitting the game now would end the run and exercise nothing, which is the opposite of what this lever is for.");
        return false;
    }
    if (g_quitFlagAddr == 0)
    {
        DebugLog("[STORE] quitmenu REFUSED: the engine's quit byte was never decoded (E26 is inert this run), so the detour could not tell a quit from a cancel; nothing was called.");
        return false;
    }
    if (QuitFlagSet() != 0)
    {
        DebugLog("[STORE] quitmenu REFUSED: the quit byte is ALREADY up - this game is on its way out and the bookkeeping has run or is running; a second entry would prove nothing.");
        return false;
    }
    if (!Plaus(coop::GameWorldPtr()) || !coop::GameplayRunning())
    {
        DebugLog("[STORE] quitmenu REFUSED: no world is running here (GameplayRunning is F337's frame-counter test, which is what tells the title screen from a live world - the GameWorld POINTER cannot, F034: it is a static in the image and is non-null from preload). The site this lever calls is the one that matters only because a world is loaded when it runs.");
        return false;
    }
    /* THIS LINE IS WRITTEN AND FLUSHED BEFORE THE CALL. After the call the quit byte is up and the process
       is leaving; DebugLog writes each line with one WriteFile (coop_log.h), so a line written first is on disk
       first. The result line below usually survives too - the flag is polled by the main loop rather than
       acted on inside this call - but it is a bonus, never the record. */
    char qm[420];
    _snprintf(qm, 419, "[STORE] quitmenu -> calling 0x%llX with result=2 (the in-game pause menu's EXIT GAME -> exit-confirm accept path, hooked by P6l; the engine raises the quit byte 0x%X bytes in and the detour then runs NoteQuitting(menu) on this thread). Written before the call because the game is on its way out after it.",
              (unsigned long long)kQuitConfirmRva, (unsigned int)kQuitConfirmStoreOff);
    qm[419] = 0;
    DebugLog(qm);
    const int rc = QuitConfirmCallPod(Base() + kQuitConfirmRva);
    char qr[300];
    _snprintf(qr, 299, "[STORE] quitmenu returned rc=%d liveFlag=%d (rc=1 the engine's exit path returned normally, rc=-1 it raised; liveFlag=1 means the quit byte is up and this game is quitting)",
              rc, QuitFlagSet());
    qr[299] = 0;
    DebugLog(qr);
    return true;
}
bool KillNamed(const std::string& needle)
{
    if (needle.empty()) { DebugLog("[STORE] killnamed: no name given"); return false; }
    if (!Plaus(coop::GameWorldPtr())) { DebugLog("[STORE] killnamed '" + needle + "' -> no GameWorld (this is a REFUSAL, not 'no match')"); return false; }
    const GameHashSet< ::Character*>::type& all = coop::GameWorldPtr()->activeCharacters();
    const size_t n = all.size();
    if (n > 20000) { DebugLog("[STORE] killnamed '" + needle + "' -> update list size " + N((long long)n) + " is implausible - refusing to walk it (this is a REFUSAL, not 'no match')"); return false; }
    /* lesson 12: the inputs, not only the answer - a bare "no match" cannot tell "nobody here is called that" from
       "everybody's name was unreadable" from "the name matched but the engine says they are not a named character". */
    /* E25.8 (review-p5p MEDIUM-3): the walk RUNS TO THE END and the kill happens after it. It used to break at the
       first match, which made `nameHits` 1 by construction on a hit - a number that reads as "how many matched" and
       reports "we stopped counting". The needle is a SUBSTRING, and the set is iterated in bucket order over hashed
       pointer values, so several uniques can match and WHICH one is picked changes between runs, between machines
       and between two loads of one save. Counting the whole walk first makes that choice visible instead of silent;
       the pick is still the first named match the set hands back, and an ambiguous target is now said out loud. */
    long long scanned = 0, unreadable = 0, nameHits = 0, notUnique = 0, named = 0;
    ::Character* pick = 0;
    char pickName[256], pickSid[256]; pickName[0] = 0; pickSid[0] = 0;
    for (GameHashSet< ::Character*>::type::const_iterator it = all.begin(); it != all.end(); ++it)
    {
        ::Character* c = *it;
        if (!Plaus(c)) { ++unreadable; continue; }
        ++scanned;
        char nm[256], sd[256];
        if (KillNamedReadPod(c, nm, 256, sd, 256) != 1) { ++unreadable; continue; }
        const std::string nameStr(nm);
        if (nameStr.find(needle) == std::string::npos) continue;
        ++nameHits;
        if (KillNamedIsUniquePod(c) != 1) { ++notUnique; continue; }   /* a FAULT reads as "not named", the safe side - exactly as the world-state gate reads it */
        ++named;
        if (pick == 0) { pick = c; std::memcpy(pickName, nm, 256); std::memcpy(pickSid, sd, 256); pickName[255] = 0; pickSid[255] = 0; }
    }
    /* lesson 12 again, and this time on EVERY terminal line: a hit that cannot be interrogated is as useless as a
       zero that cannot be. The same inputs are printed whether the lever hit, missed or faulted. */
    const std::string inputs = " (walked=" + N(scanned) + " unreadable=" + N(unreadable)
                             + " nameHits=" + N(nameHits) + " nameHitsNotNamedCharacter=" + N(notUnique)
                             + " namedMatches=" + N(named) + ")";
    if (pick == 0) { DebugLog("[STORE] killnamed '" + needle + "' -> no match" + inputs); return false; }
    if (named > 1)
        ErrorLog("[STORE] killnamed '" + needle + "' -> AMBIGUOUS: " + N(named) + " named characters match this substring;"
                 " killing the first the engine's set handed back, which is not a stable choice" + inputs);
    const unsigned int uid = FindSpawnedUid(pick);
    const std::string sidStr(pickSid), nameStr(pickName);
    if (StoreDeclareDeadPod(pick) != 1)
    {
        ErrorLog("[STORE] killnamed '" + needle + "' -> uid=" + N((long long)uid) + " sid=" + sidStr + " name='" + nameStr + "' declareDead FAULTED" + inputs);
        return false;
    }
    /* par6 fold (review-par6 #3): the call returning is not a death - a copy's declareDead is refused by the copy death gate */
    if (StoreIsDeadPod(pick) != 1)
    {
        DebugLog("[STORE] killnamed '" + needle + "' -> uid=" + N((long long)uid) + " sid=" + sidStr + " name='" + nameStr + "' refused (a copy - the owner decides)" + inputs);
        return false;
    }
    DebugLog("[STORE] killnamed '" + needle + "' -> uid=" + N((long long)uid) + " sid=" + sidStr + " name='" + nameStr + "' declared dead" + inputs);
    return true;
}
}
