/* E38 - THE CLIENT'S NOTEBOOK ADDRESS, AS THE HOST NAMED IT. Called from OnWelcome (net/session.cpp) at the
   title screen. SetStoreServer is idempotent for the address already open (see its own guard), so a host whose
   `store=` matches the client's own file costs nothing here; a host that names a DIFFERENT notebook wins, which
   is decision 42's rule - the host knows which notebook its world belongs to and the client's file is a guess. */
void StoreLinkFromWelcome(const std::string& address, unsigned short port)
{
    if (address.empty() || port == 0) return;
    if (g_link != 0 && g_linkAddr == address && g_linkPort == port) return;   /* already there - logged by SetStoreServer's own guard if it is reached */
    DebugLog("[STORE] E38: the host's session welcome names the notebook at " + relaybridge::AddrForLog(address) + ":" + N((long long)port)
             + " - opening it now, at the title screen, so this game's world load can wait for its first area map.");
    SetStoreServer(address, port);
}

/* E38 - A VERB TOOK THIS GAME OUT OF SINGLE-PLAYER. The index was deliberately not read at InstallStore under
   role=single; a `join` or `store server` typed later means the folder is a co-op world's after all, so its
   folders are named now and the index is read at the notebook's WELCOME (W3-f). Recurrence-covered rather than swept for: the one event that changes the answer is the one that
   calls this. */
void StoreRoleLeftSingle()
{
    if (!g_dirReady || g_indexLoaded) return;
    DebugLog("[STORE] a command-channel verb took this game out of role=single - the folders of world '" + ConfigWorldKey() + "' are named now; they are created and its notebook record index is read when the notebook's WELCOME names the world this game follows (W3-f: every co-op game reads its index there, never here).");
    StoreArmWorldIndex("roleLeftSingle");   /* P7i (T233 section 5): the folders were not made at install under role=single - StoreArmWorldIndex makes them in the same breath as the index read, which is the only reason either of them exists */
}

/* T-985 C2b fold 1 (review MED 3) + fold 2 (re-check LOW 2, LOW 4): 1 = this people check waits for the feed - a group row the load
   left for the feed lies in or beside the asked area (townpending::HoldsNear: the row's town is not known here, so an area merely
   loaded here says nothing about this town). A wait a not-whole snapshot END left on ends here kPreTownWaitNotWholeMs after that
   END, counted (townWaitTimedOut) and said with the towns it refused (fold 5). ANY THREAD: the list is copied under its lock and asked outside it. T-985 C2b fold 3 (re-check
   LOW, thread race): the bound is read and the wait ended under that same lock, which PreTownWaitSet arms a new wait under, so an
   expired bound ends only the wait it timed (townpending::BoundPassed: the tick's wrap). */
int PreTownWaitAsk(int askSx, int askSy, char* holderOut, int holderCap)
{
    if (::InterlockedCompareExchange(&g_preTownWaitOn, 0, 0) == 0 || !g_preStaleLockInit) return 0;
    std::vector<int> xy; bool ended = false, timedOut = false;
    ::EnterCriticalSection(&g_preStaleLock);
    const LONG nw = ::InterlockedCompareExchange(&g_preTownWaitNotWholeAt, 0, 0);
    if (nw != 0 && townpending::BoundPassed((unsigned int)nw, (unsigned int)::GetTickCount(), (unsigned int)kPreTownWaitNotWholeMs) != 0)
    {
        ended = true;
        timedOut = ::InterlockedExchange(&g_preTownWaitOn, 0) != 0;
    }
    else xy = g_preTownWaitAreas;
    ::LeaveCriticalSection(&g_preStaleLock);
    if (timedOut)
    {   /* T-985 C2b fold 5 (T1533): this end was counted with no line - it is said, with the towns the wait refused (once: only the
           ask that switched the wait off gets here) */
        ::InterlockedIncrement64(&g_preTownWaitTimedOut);
        DebugLog("[STORE] T-985 C2b: the load's town wait has ended by its time bound - no whole feed snapshot came within " + N((long long)(kPreTownWaitNotWholeMs / 1000))
                 + " s of one not seen whole; towns beside the group records left out of the load's fetch no longer wait (preAoi townWaitTimedOut)");
        PreTownWaitRefusedSay("the wait has ended by its time bound");
    }
    if (ended) return 0;
    for (size_t k = 0; k + 1 < xy.size(); k += 2)
    {
        if (townpending::HoldsNear(xy[k], xy[k + 1], askSx, askSy) == 0) continue;
        ::InterlockedIncrement64(&g_preTownWaits);
        if (holderOut != 0 && holderCap > 1)
        {
            _snprintf(holderOut, (size_t)(holderCap - 1), "%s in area %d,%d (waits for the feed)", kPreTownWaitHolder, xy[k], xy[k + 1]);
            holderOut[holderCap - 1] = 0;
        }
        return 1;
    }
    return 0;
}
/* T-985 C2b fold 2 (re-check LOW 3): towngen's plain refusal of a creation held by the load's town wait (known by its holder text) -
   counted, and its town kept to be named when the wait ends (PreTownWaitRefusedSay). ANY THREAD. */
void StorePreTownWaitRefused(const char* townSid, const char* holder)
{
    if (townSid == 0 || townSid[0] == 0 || holder == 0 || std::strstr(holder, kPreTownWaitHolder) == 0 || !g_preStaleLockInit) return;
    ::InterlockedIncrement64(&g_preTownWaitRefused);
    bool fresh = false;
    ::EnterCriticalSection(&g_preStaleLock);
    if (g_preTownWaitRefusedTowns.size() < 512) fresh = g_preTownWaitRefusedTowns.insert(std::string(townSid)).second;
    ::LeaveCriticalSection(&g_preStaleLock);
    if (fresh) ::InterlockedIncrement64(&g_preTownWaitRefusedTownsN);
}
int StoreTownPeoplePending(const char* townSid, int askSx, int askSy, char* holderOut, int holderCap)
{
    if (holderOut != 0 && holderCap > 0) holderOut[0] = 0;
    /* E38 (e): with no co-op role there is no notebook and no other game, so nothing can be pending. The set is
       empty under role=single anyway (the index is not read), and this is the belt to that pair of braces - it is
       also where the ANY-THREAD readers in towngen get their answer, so the test lives on the cheap side. */
    if (RoleIsSingle()) return townpending::kTownNotListed;
    if (townSid == 0 || townSid[0] == 0) return townpending::kTownNotListed;
    if (PreTownWaitAsk(askSx, askSy, holderOut, holderCap) != 0) return townpending::kTownHeld;   /* T-985 C2b fold 1 (review MED 3): its people may not be known here yet */
    std::vector<PendArea> areas;
    PendingLockInit(); ::EnterCriticalSection(&g_pendingLock);
    { const std::map<std::string, std::vector<PendArea> >::const_iterator f = g_pendingTownsTS.find(std::string(townSid)); if (f != g_pendingTownsTS.end()) areas = f->second; }
    ::LeaveCriticalSection(&g_pendingLock);   /* the copy is asked below, outside this lock: SectorLoadedHereTS takes the zones' own lock */
    /* T-580: a listed note holds the town from an area this game has loaded, from the asked area (the town's, or the creation's
       spawn position) and its ring 1 (loading now), with no position known here, or when the asked area is unread (-1). A note no game can place is not listed (PublishPendingTowns). A note sleeping in an area this game does not load is placed if and when that area loads - until then
       the engine's own count of the town's squads cannot include it, and refusing on it would keep the town empty for good. */
    for (size_t i = 0; i < areas.size(); ++i)
    {
        coop::Sector sec; sec.x = areas[i].sx; sec.y = areas[i].sy;
        const int loaded = coop::SectorLoadedHereTS(sec) == 1 ? 1 : 0;
        if (townpending::Holds(sec.x, sec.y, loaded, askSx, askSy) == 0) continue;
        if (holderOut != 0 && holderCap > 1)
        {
            if (sec.x < 0) _snprintf(holderOut, (size_t)(holderCap - 1), "%s (position not known here)", areas[i].worldId.c_str());
            else _snprintf(holderOut, (size_t)(holderCap - 1), "%s in area %d,%d (%s)", areas[i].worldId.c_str(), sec.x, sec.y,
                           loaded != 0 ? "loaded here" : (askSx < 0 || askSy < 0) ? "town area unread" : "in or beside the town's area");
            holderOut[holderCap - 1] = 0;
        }
        return townpending::TownAnswer((int)areas.size(), 1);
    }
    return townpending::TownAnswer((int)areas.size(), 0);
}
/* T-698 / T-798 (b): THE SAME QUESTION FOR ONE BUILDING'S RESIDENTS, MAIN THREAD (the re-offer and the repair). A listed note of the
   town that holds it from its area (townpending::Holds, as above) holds the building only when its record's home key (RecordHomeOf)
   is the building's key, or - a note with no home key - its record's squad template is the building's resident template and its
   record position is within kNoteKeylessRadius of the building (townpending::NoteHoldsBuilding). A note homed at another building
   does not hold this one; a note that cannot be told (no record here, a template or its record position not known) holds every
   building of its town. */
const float kNoteKeylessRadius = 30.0f;   /* towngen.cpp kT591KeylessRadius */
int StoreBuildingPeoplePending(const char* townSid, const char* buildingKey, void* bldTemplate, float bx, float bz, int askSx, int askSy, char* holderOut, int holderCap)
{
    if (holderOut != 0 && holderCap > 0) holderOut[0] = 0;
    if (RoleIsSingle()) return townpending::kTownNotListed;
    if (townSid == 0 || townSid[0] == 0 || buildingKey == 0) return townpending::kTownNotListed;
    if (PreTownWaitAsk(askSx, askSy, holderOut, holderCap) != 0) return townpending::kTownHeld;   /* T-985 C2b fold 1 (review MED 3): as the town's answer */
    const std::map<std::string, std::vector<PendArea> >::const_iterator f = g_pendingNotesByTown.find(std::string(townSid));
    if (f == g_pendingNotesByTown.end() || f->second.empty()) return townpending::kTownNotListed;
    const std::string bkey(buildingKey);
    std::string tsid; int tsidRead = -1;   /* the building's template stringID, read once when a keyless note asks */
    for (size_t i = 0; i < f->second.size(); ++i)
    {
        const PendArea& n = f->second[i];
        coop::Sector sec; sec.x = n.sx; sec.y = n.sy;
        const int loaded = coop::SectorLoadedHereTS(sec) == 1 ? 1 : 0;
        if (townpending::Holds(sec.x, sec.y, loaded, askSx, askSy) == 0) continue;
        const int test = g_testPendNotes.count(n.worldId) != 0 ? 1 : 0;
        const std::string home = RecordHomeOf(n.worldId);
        int recHere = 0, tmplKnown = 0, tmplMatch = 0, posKnown = 0; float dx = 0.0f, dz = 0.0f;
        if (test == 0 && home.empty())
        {
            const std::map<std::string, Record>::const_iterator rt = g_records.find(n.worldId);
            if (rt != g_records.end())
            {
                recHere = 1;
                if (tsidRead < 0)
                {
                    char buf[160]; buf[0] = 0;
                    tsidRead = (Plaus(bldTemplate) && CopyStdStringPod((const char*)bldTemplate + 0x58, buf, 160)) ? 1 : 0;   /* GameData stringID, as the record's squadSid is read */
                    if (tsidRead == 1) tsid = buf;
                }
                tmplKnown = (tsidRead == 1 && !tsid.empty() && !rt->second.squadSid.empty()) ? 1 : 0;   /* both templates known */
                tmplMatch = (tmplKnown != 0 && rt->second.squadSid == tsid) ? 1 : 0;
                posKnown = (rt->second.x == 0.0f && rt->second.z == 0.0f) ? 0 : 1;   /* (0,0) = never written */
                dx = rt->second.x - bx; dz = rt->second.z - bz;
            }
        }
        if (townpending::NoteHoldsBuilding(test, home, bkey, recHere, tmplKnown, tmplMatch, posKnown, dx, dz, kNoteKeylessRadius) == 0) continue;
        if (holderOut != 0 && holderCap > 1)
        {
            if (sec.x < 0) _snprintf(holderOut, (size_t)(holderCap - 1), "%s (position not known here; %s)", n.worldId.c_str(), home.empty() ? "no home key" : "homed here");
            else _snprintf(holderOut, (size_t)(holderCap - 1), "%s in area %d,%d (%s; %s)", n.worldId.c_str(), sec.x, sec.y,
                           loaded != 0 ? "loaded here" : (askSx < 0 || askSy < 0) ? "town area unread" : "in or beside the town's area", home.empty() ? "no home key" : "homed here");
            holderOut[holderCap - 1] = 0;
        }
        return townpending::kTownHeld;
    }
    return townpending::kTownElsewhere;
}
/* TEST-ONLY (storetest verb), MAIN THREAD: storetest nopos <worldId or part of one> - the next SLEEP write of that group reads as if
   no member of it were in the world and its platoon stood at 0,0, so a run can watch the record take a known position
   (RecordPosChoose); storetest nopos next arms the next SLEEP write of any group. An exact worldId wins; else the first record here (in worldId order) whose id contains the text, else the
   first group bound here. storetest nopos off disarms. [STORE] storetest lines. */
std::string StoreTestCommand(const std::string& arg)
{
    const size_t sp = arg.find(' ');
    const std::string op = sp == std::string::npos ? arg : arg.substr(0, sp);
    std::string rest = sp == std::string::npos ? std::string() : arg.substr(sp + 1);
    while (!rest.empty() && rest[0] == ' ') rest.erase(0, 1);
    if (op != "nopos" || rest.empty()) return "error storetest usage: storetest nopos <worldId or part of one> | storetest nopos off";
    if (rest == "off") { g_recPosNoPosArmed.clear(); DebugLog("[STORE] storetest nopos off: nothing armed"); return "ok storetest nopos off"; }
    if (rest == "next") { g_recPosNoPosArmed = "*"; DebugLog("[STORE] storetest nopos armed for the next SLEEP write of any group"); return "ok storetest nopos armed for the next SLEEP write"; }
    std::string found;
    if (g_records.count(rest) != 0) found = rest;
    for (std::map<std::string, Record>::const_iterator it = g_records.begin(); found.empty() && it != g_records.end(); ++it)
        if (it->first.find(rest) != std::string::npos) found = it->first;
    for (std::map<void*, std::string>::const_iterator bi = g_bind.begin(); found.empty() && bi != g_bind.end(); ++bi)
        if (bi->second.find(rest) != std::string::npos) found = bi->second;
    if (found.empty()) { DebugLog("[STORE] storetest nopos: no group here matches '" + rest + "' - nothing armed"); return "error storetest nopos: no group matches"; }
    g_recPosNoPosArmed = found;
    DebugLog("[STORE] storetest nopos armed for " + found);
    return "ok storetest nopos armed for " + found;
}
/* TEST-ONLY (pendnote verb, T-580), MAIN THREAD: pendnote add <townSid> <x> <z> [stale|asleep] lists a test note of that town at world
   position (x, z) in decision 34's pending set, asked and listed as a notebook note this game has not placed is. Its id: none given -
   an unnumbered test id (whose it is cannot be told); stale - a group id numbered in this game's own block that this game's world
   does not hold (the faction of a group asleep here, the number at the top of the block); asleep - the id of a group asleep in this
   game's world. pendnote clear removes every test note; pendnote show <townSid> <x> <z> answers the town's question for a creation
   in the area of (x, z). [STORE] pendnote lines. */
std::string StorePendNoteCommand(const std::string& op, const std::string& town, float x, float z, const std::string& kind)
{
    const std::string usage("error pendnote: usage pendnote add <townSid> <x> <z> [stale|asleep] | clear | show <townSid> <x> <z>");
    std::string line;
    if (op == "clear")
    {
        const long long n = (long long)g_testPendNotes.size(); g_testPendNotes.clear(); PublishPendingTowns();
        line = "[STORE] pendnote clear: " + N(n) + " test note(s) removed (TEST-ONLY)";
        DebugLog(line); return line;
    }
    if (town.empty()) return usage;
    const Sector sec = SectorOf(x, z);
    if (op == "add")
    {
        std::string id, facKey;
        if (kind.empty()) id = "SWTEST-pendnote-" + N(++g_testPendSeq);
        else if (kind == "stale" || kind == "asleep")
        {
            std::string wid; ::Faction* f = 0;
            if (!PendNotePickAsleep(&wid, &f)) { line = "error pendnote: no NPC group is asleep in this game's world to take an id or a faction from - nothing added"; DebugLog(line); return line; }
            facKey = FactionKey(f);
            if (kind == "asleep") id = wid;
            else
            {
                const int mine = NoteOwnBlock();
                if (mine < 0) { line = "error pendnote: this game's own number block is not known yet - nothing added"; DebugLog(line); return line; }
                id = std::string(f->getName()) + "_" + N((long long)mine * 65536 + 65535 - (++g_testPendSeq));
            }
        }
        else return usage;
        TestPendNote t; t.town = town; t.x = x; t.z = z; t.factionKey = facKey; g_testPendNotes[id] = t;
        int one = 1, holderIn = -1;
        const int place = facKey.empty() ? townpending::kPlaceUnknown : NotePlaceable(id, facKey, town, 1, x, z, &one, 0);
        const int engine = facKey.empty() ? -1 : NoteEngineHasNow(id, facKey), held = NoteAreaHeld(1, x, z, &holderIn);
        PublishPendingTowns();
        line = "[STORE] pendnote add " + id + " town='" + town + "' pos=" + F1(x) + "," + F1(z) + " area " + N((long long)sec.x) + "," + N((long long)sec.y)
             + " loadedHere=" + N((long long)SectorLoadedHereTS(sec)) + " block=" + N((long long)GroupBlockOwner(id)) + " mySlot=" + N((long long)g_mySlot) + " ownBlock=" + N((long long)NoteOwnBlock())
             + " engine=" + N((long long)engine) + " areaHeld=" + N((long long)held) + " holder=" + N((long long)coop::AreaHolderSlotTS(sec)) + " holderInWorld=" + N((long long)holderIn)
             + " recordUsable=" + N((long long)(NoteRecordUsable(id) != 0 ? 1 : 0)) + " placeable=" + PlaceName(place) + " (TEST-ONLY: listed as a notebook note of the town this game has not placed)";
    }
    else if (op == "show")
    {
        char holder[192];
        const int a = StoreTownPeoplePending(town.c_str(), sec.x, sec.y, holder, 192);
        line = "[STORE] pendnote show town='" + town + "' asked for area " + N((long long)sec.x) + "," + N((long long)sec.y) + " -> "
             + (a == townpending::kTownHeld ? std::string("held by ") + holder : a == townpending::kTownElsewhere ? std::string("listed elsewhere (not held)") : std::string("not listed"));
    }
    else return usage;
    DebugLog(line); return line;
}
void NoteTownPeople(const std::string& worldId, const std::string& town)
{
    if (worldId.empty()) return;
    if (town.empty()) { ++g_noteTownEmpty; return; }   /* review-p4x HIGH: an empty town is "unknown", NOT "no town" - the mark and the record must not diverge; only a delete erases */
    if (town == "-")
    {
        /* review-p5a MEDIUM-1: the sender says this group HAS no home town (it left one, or never had one). This is the one
           legitimate erase, and it is now distinguishable from a faulted read and from a sender too old to say. */
        const bool changed = g_pendingTown.erase(worldId) != 0;
        std::map<std::string, Record>::iterator itn = g_records.find(worldId);
        if (itn != g_records.end()) itn->second.town.clear();
        ++g_noteTownNone;
        if (changed && !g_publishSuppressed) PublishPendingTowns();
        return;
    }
    const bool changed = (g_pendingTown.count(worldId) == 0 || g_pendingTown[worldId] != town);
    g_pendingTown[worldId] = town;
    std::map<std::string, Record>::iterator it = g_records.find(worldId); if (it != g_records.end()) it->second.town = town;
    if (changed && !g_publishSuppressed) PublishPendingTowns();   /* review-p4x MEDIUM: on change, not only per 118 frames (after a teardown the set was stale for up to two seconds) */   /* review-p5a MEDIUM-2: except inside a burst, which publishes once at its end */
}
